import { jsPDF } from 'jspdf';
import { ReceiptData } from '../types';

export async function getReceiptBlob(data: ReceiptData): Promise<Blob> {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4'
  });

  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();

  // Header Blue
  doc.setFillColor(30, 64, 175);
  doc.rect(0, 0, pageWidth, 40, 'F');

  // Logo text
  doc.setTextColor(255, 255, 255);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(24);
  doc.text('BelConfort', 15, 20);
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text('CAMAS E MÓVEIS', 15, 25);

  // Company Info
  doc.setFontSize(7);
  doc.text('CNPJ 60.190.028/0001-60', pageWidth - 15, 15, { align: 'right' });
  doc.text('RUA B, 103C, CASTANHEIRA - BELEM/PA', pageWidth - 15, 20, { align: 'right' });
  doc.text('belconfortcamasemoveis@gmail.com', pageWidth - 15, 25, { align: 'right' });
  doc.text('(91) 99381-2592', pageWidth - 15, 30, { align: 'right' });

  // Title
  doc.setTextColor(31, 41, 55);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('COMPROVANTE DE COMPRA', pageWidth / 2, 55, { align: 'center' });

  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(107, 114, 128);
  const now = new Date();
  doc.text(`Emissão: ${now.toLocaleDateString('pt-BR')} às ${now.toLocaleTimeString('pt-BR')}`, pageWidth / 2, 60, { align: 'center' });

  // Client Data Box
  let y = 70;
  doc.setDrawColor(209, 213, 219);
  doc.setLineWidth(0.2);
  doc.line(15, y, pageWidth - 15, y); // Top line

  // Cells Data
  doc.setFontSize(7);
  doc.setTextColor(156, 163, 175);
  doc.text('DATA DO PEDIDO', 17, y + 4);
  doc.text('CLIENTE', 55, y + 4);
  doc.text('CPF/CNPJ', 155, y + 4);

  doc.setFontSize(9);
  doc.setTextColor(31, 41, 55);
  doc.text(data.date ? new Date(data.date + 'T12:00:00').toLocaleDateString('pt-BR') : '-', 17, y + 9);
  doc.text(data.name || '-', 55, y + 9);
  doc.text(data.cpf || '-', 155, y + 9);

  y += 15;
  doc.line(15, y, pageWidth - 15, y); // Row line

  // Products Table Header
  y += 10;
  doc.setFillColor(249, 250, 251);
  doc.rect(15, y, pageWidth - 30, 8, 'F');
  doc.line(15, y, pageWidth - 15, y);
  doc.line(15, y + 8, pageWidth - 15, y + 8);

  doc.setFontSize(7);
  doc.setFont('helvetica', 'bold');
  doc.text('CÓD', 17, y + 5);
  doc.text('DESCRIÇÃO DO PRODUTO', 35, y + 5);
  doc.text('QTD', 135, y + 5, { align: 'center' });
  doc.text('UNITÁRIO', 155, y + 5, { align: 'right' });
  doc.text('TOTAL', pageWidth - 17, y + 5, { align: 'right' });

  // Product Rows
  y += 8;
  doc.setFont('helvetica', 'normal');
  data.products.forEach((p, i) => {
    doc.setFontSize(8);
    doc.text(p.code || '-', 17, y + 6);
    doc.text(p.name, 35, y + 6);
    doc.text(p.quantity.toString(), 135, y + 6, { align: 'center' });
    doc.text(p.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 }), 155, y + 6, { align: 'right' });
    doc.text((p.price * p.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 }), pageWidth - 17, y + 6, { align: 'right' });

    if (p.warrantyTime) {
      y += 4;
      doc.setFontSize(6);
      doc.setTextColor(156, 163, 175);
      doc.text(`GARANTIA DE FÁBRICA: ${p.warrantyTime} ${p.warrantyUnit} | 90 DIAS LOJA`, 35, y + 5);
    }

    y += 8;
    doc.setDrawColor(243, 244, 246);
    doc.line(15, y, pageWidth - 15, y);
    doc.setTextColor(31, 41, 55);
  });

  // Totals
  y += 10;
  const subtotal = data.products.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const bundleDiscount = data.bundleDiscount || 0;
  const manualDiscount = data.discountType === 'fixed' ? data.discountValue : subtotal * (data.discountValue / 100);
  const total = subtotal - bundleDiscount - manualDiscount;

  doc.setFontSize(8);
  doc.text('Subtotal:', 140, y);
  doc.text(subtotal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }), pageWidth - 17, y, { align: 'right' });

  if (bundleDiscount > 0) {
    y += 5;
    doc.setTextColor(37, 99, 235);
    doc.text(`${data.bundleLabel || 'Desconto Combo'}:`, 140, y);
    doc.text(`- ${bundleDiscount.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`, pageWidth - 17, y, { align: 'right' });
  }

  if (manualDiscount > 0) {
    y += 5;
    doc.setTextColor(220, 38, 38);
    doc.text('Desc. Vendedor:', 140, y);
    doc.text(`- ${manualDiscount.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`, pageWidth - 17, y, { align: 'right' });
  }

  y += 7;
  doc.setTextColor(31, 41, 55);
  doc.setFont('helvetica', 'bold');
  doc.setFillColor(249, 250, 251);
  doc.rect(135, y - 5, pageWidth - 135 - 15, 8, 'F');
  doc.text('TOTAL:', 140, y);
  doc.text(total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }), pageWidth - 17, y, { align: 'right' });

  // Policy Footer
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7);
  doc.setTextColor(107, 114, 128);
  const footerText = "Direito de Arrependimento (Art. 49 CDC): 7 dias para compras online. Garantia legal de 90 dias.";
  doc.text(footerText, pageWidth / 2, pageHeight - 15, { align: 'center' });

  return doc.output('blob');
}

export async function generateReceiptPDF(data: ReceiptData): Promise<void> {
  const blob = await getReceiptBlob(data);
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `COMPROVANTE - ${data.name || 'CLIENTE'}.pdf`;
  link.click();
  URL.revokeObjectURL(url);
}

