const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export async function parseReceiptFromText(text: string, catalogNames: string[]) {
  const prompt = `
    Analise o seguinte texto de pedido e extraia os dados do cliente e os itens.
    Use os nomes exatos do catálogo para os produtos quando houver correspondência.

    TEXTO:
    "${text}"

    CATÁLOGO DISPONÍVEL:
    ${catalogNames.join(', ')}

    Responda APENAS com o JSON no formato:
    {
      "clientData": {
        "name": "Nome do Cliente",
        "cpf": "CPF se houver",
        "email": "Email se houver",
        "street": "Rua",
        "number": "Número",
        "neighborhood": "Bairro",
        "city": "Cidade",
        "complement": "Complemento",
        "contact1": "Telefone 1",
        "contact2": "Telefone 2"
      },
      "items": [
        { "name": "NOME EXATO DO CATALOGO", "quantity": 1 }
      ]
    }
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json"
    }
  });

  return JSON.parse(response.text || "{}");
}

